INSERT INTO public.ai_insights (iddesa, kondisi_ekonomi, rekomendasi_aktor, teks_lengkap)
VALUES (
    '1801040001',
    'Desa Kubu Perahu saat ini berada dalam Zona Mitra dengan status IDM Mandiri, menunjukkan kemandirian tata kelola yang matang dan kapasitas fiskal yang memadai. Berdasarkan struktur ekonominya, desa ini didominasi oleh peran sebagai Simpul Logistik dengan skor mencapai 97,78%, serta ditopang secara kuat oleh sektor perikanan (94,44%) dan kehutanan (91,85%). Kombinasi antara fungsi simpul logistik yang strategis dan komoditas unggulan berbasis perikanan serta hutan menjadikan Kubu Perahu sebagai pusat distribusi dan agregasi ekonomi yang sangat potensial di kawasan regionalnya.',
    '[{"aksi": "Menggunakan Dana Desa untuk memperkuat pemberdayaan ekonomi masyarakat dan BUMDes agar roda perekonomian lokal semakin mandiri dan produktif.", "aktor": "Pemerintah Desa"}, {"aksi": "Memasukkan desa ini ke dalam program Desa Ekspor dan Desa BISA, memanfaatkan skor potensi yang sangat tinggi untuk memperluas jangkauan pasar komoditas unggulan.", "aktor": "Pemerintah Pusat dan Daerah"}, {"aksi": "Mengambil peran melalui skema Kemitraan Swasta (Logistik) untuk berinvestasi dalam pembangunan gudang, fasilitas penyimpanan, atau pusat distribusi guna mengoptimalkan posisi strategis desa sebagai simpul logistik utama.", "aktor": "Swasta"}]'::jsonb,
    'Desa Kubu Perahu saat ini berada dalam Zona Mitra dengan status IDM Mandiri, menunjukkan kemandirian tata kelola yang matang dan kapasitas fiskal yang memadai. Berdasarkan struktur ekonominya, desa ini didominasi oleh peran sebagai Simpul Logistik dengan skor mencapai 97,78%, serta ditopang secara kuat oleh sektor perikanan (94,44%) dan kehutanan (91,85%). Kombinasi antara fungsi simpul logistik yang strategis dan komoditas unggulan berbasis perikanan serta hutan menjadikan Kubu Perahu sebagai pusat distribusi dan agregasi ekonomi yang sangat potensial di kawasan regionalnya.\n\nBerikut adalah rekomendasi aksi spesifik untuk para aktor terkait:\n- **Pemerintah Desa** dapat menggunakan **Dana Desa** untuk memperkuat pemberdayaan ekonomi masyarakat dan BUMDes agar roda perekonomian lokal semakin mandiri dan produktif.\n- **Pemerintah Pusat dan Daerah** didorong untuk memasukkan desa ini ke dalam program **Desa Ekspor** dan **Desa BISA**, memanfaatkan skor potensi yang sangat tinggi untuk memperluas jangkauan pasar komoditas unggulan.\n- **Swasta** dapat mengambil peran melalui skema **Kemitraan Swasta (Logistik)** untuk berinvestasi dalam pembangunan gudang, fasilitas penyimpanan, atau pusat distribusi guna mengoptimalkan posisi strategis desa sebagai simpul logistik utama.'
);
